import{Ct as e,at as t,it as n,o as r,ot as i,st as a,tt as o,yt as s}from"./chunks/framework.B-d2E8F-.js";var c={class:`mockup pr`,role:`group`,"aria-label":`TeXRA code review on a pull request`},l={class:`pr-head`},u={class:`pr-avatar`,"aria-hidden":`true`},d={class:`pr-head-body`},f={class:`pr-head-sub`},p={class:`pr-inline`},m={class:`pr-file`},h={class:`pr-thread`},g={class:`pr-comment`},_={class:`pr-c-avatar`,"aria-hidden":`true`},v={class:`pr-c-body`},y={class:`pr-c-head`},b={class:`pr-c-badge`},x=r({__name:`PrReviewCard`,setup(r){return(r,x)=>{let S=e(`wa-icon`);return s(),n(`div`,c,[o(`div`,l,[o(`span`,u,[a(S,{library:`texra`,name:`robot`})]),o(`div`,d,[x[1]||=t(`<div class="pr-head-line" data-v-3b1dc317><span class="pr-actor" data-v-3b1dc317>github-actions</span><span class="pr-bot" data-v-3b1dc317>bot</span><span class="pr-action" data-v-3b1dc317>reviewed</span><span class="pr-time" data-v-3b1dc317>2 hours ago</span></div>`,1),o(`div`,f,[a(S,{class:`pr-sub-ic`,library:`texra`,name:`robot`}),x[0]||=i(` TeXRA Code Review `,-1)])]),x[2]||=o(`span`,{class:`pr-verdict`},`Changes requested`,-1)]),x[9]||=o(`div`,{class:`pr-summary`},[o(`div`,{class:`pr-summary-bar`}),o(`div`,{class:`pr-summary-body`},[i(` 2 issues worth a look, otherwise looks good. The new `),o(`code`,{class:`pr-code`},`summarize()`),i(` path needs an empty-input guard before it indexes, and one log line leaks a token. `)])],-1),o(`div`,p,[o(`div`,m,[a(S,{class:`pr-file-ic`,library:`texra`,name:`file-code`}),x[3]||=o(`span`,{class:`pr-file-name`},`src/agent/summarize.ts`,-1)]),x[8]||=t(`<div class="pr-diff" data-v-3b1dc317><div class="dl" data-v-3b1dc317><span class="gut" data-v-3b1dc317>41</span><span class="kw" data-v-3b1dc317>export function</span> summarize(items) { </div><div class="dl add" data-v-3b1dc317><span class="gut" data-v-3b1dc317>42</span>\xA0\xA0<span class="kw" data-v-3b1dc317>const</span> first = items[<span class="m" data-v-3b1dc317>0</span>].text; </div><div class="dl" data-v-3b1dc317><span class="gut" data-v-3b1dc317>43</span>\xA0\xA0<span class="kw" data-v-3b1dc317>return</span> first.slice(<span class="m" data-v-3b1dc317>0</span>, <span class="m" data-v-3b1dc317>80</span>); </div></div>`,1),o(`div`,h,[o(`div`,g,[o(`span`,_,[a(S,{library:`texra`,name:`robot`})]),o(`div`,v,[o(`div`,y,[x[5]||=o(`span`,{class:`pr-c-actor`},`github-actions[bot]`,-1),o(`span`,b,[a(S,{library:`texra`,name:`rotate-right`}),x[4]||=i(` Updated on re-push `,-1)])]),x[6]||=o(`div`,{class:`pr-c-text`},[i(` Guard against the empty-array case here — `),o(`code`,{class:`pr-code`},`items[0]`),i(` throws when `),o(`code`,{class:`pr-code`},`items`),i(` is `),o(`code`,{class:`pr-code`},`[]`),i(`. Return early or default the slice. `)],-1)])]),x[7]||=o(`div`,{class:`pr-reply`},`Reply to this thread…`,-1)])])])}}},[[`__scopeId`,`data-v-3b1dc317`]]),S=JSON.parse(`{"title":"Code review","description":"","frontmatter":{},"headers":[],"relativePath":"guide/code-review.md","filePath":"guide/code-review.md"}`),C=Object.assign({name:`guide/code-review.md`},{setup(e){return(e,r)=>(s(),n(`div`,null,[r[0]||=t(`<h1 id="code-review" tabindex="-1">Code review <a class="header-anchor" href="#code-review" aria-label="Permalink to “Code review”">​</a></h1><p>The <strong>TeXRA Code Review</strong> GitHub Action posts a pull request review on each PR: a short summary at the top, and inline comments on the lines TeXRA wants to flag.</p><p>It runs from your own GitHub Actions environment, using model provider API keys you put in your repo&#39;s secrets. Your code and diffs are not sent through any TeXRA service; only a GitHub-signed workload identity is exchanged for a short-lived TeXRA GitHub App token.</p><p>This page walks through the whole setup from zero; no prior GitHub Actions experience is needed. Short version: from the repo, run <code>texra install-github-action</code>, then set one provider API key secret.</p><h2 id="what-you-ll-see-on-a-pr" tabindex="-1">What you&#39;ll see on a PR <a class="header-anchor" href="#what-you-ll-see-on-a-pr" aria-label="Permalink to “What you&#39;ll see on a PR”">​</a></h2><p>Once installed, every PR gets a single review from <code>texra-ai-bot[bot]</code>: a summary comment at the top with TeXRA&#39;s overall verdict, plus inline comments on the lines it wants to question. On the next push to the same PR, TeXRA updates those same threads instead of posting duplicates.</p>`,6),a(x),r[1]||=t(`<p class="hero-caption">One review per PR: a top-level verdict plus inline comments pinned to the flagged lines, refreshed in place on the next push.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How it works”">​</a></h2><p>If you have not used GitHub Actions before, here is the whole picture:</p><ul><li><strong>GitHub Actions</strong> is GitHub&#39;s built-in automation service. You describe a job in a YAML file inside your repo (under <code>.github/workflows/</code>), and GitHub runs it on its own servers whenever the trigger you chose fires. Here, that is whenever a pull request is opened or updated.</li><li><strong>The job checks out your PR and asks an AI model to review the diff.</strong> It installs the <a href="./texra-cli.html">TeXRA CLI</a>, feeds it the pull request diff plus any files the model wants to read, and posts the result back as a normal GitHub review.</li><li><strong>The model call uses <em>your</em> API key</strong>, stored as an encrypted repository <em>secret</em>. The diff travels directly from GitHub&#39;s runner to your model provider (Anthropic, OpenAI, Google, …). There is no TeXRA server in the middle, and no TeXRA account or sign-in is needed.</li><li><strong>Cost:</strong> each review is one ordinary API call billed to your key by the provider. The price depends on the model you pick and the size of the diff. For typical PRs it is small, but very large diffs on premium models cost more.</li></ul><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to “What you need”">​</a></h2><ul><li>A GitHub repository you administer, with Actions enabled (default on GitHub).</li><li>The <a href="./texra-cli.html">TeXRA CLI</a> installed locally (<code>npm i -g @texra-ai/cli</code>), plus <a href="https://cli.github.com/" target="_blank" rel="noreferrer"><code>gh</code></a> authenticated for opening the workflow PR (<code>gh auth login</code>).</li><li>An API key from at least one model provider. Prefer open-weight options when you can (DeepSeek, OpenRouter); Anthropic, OpenAI, Google, and xAI also work.</li></ul><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to “Setup”">​</a></h2><h3 id="quick-setup-recommended" tabindex="-1">Quick setup (recommended) <a class="header-anchor" href="#quick-setup-recommended" aria-label="Permalink to “Quick setup (recommended)”">​</a></h3><p>From a clone of the repository you want TeXRA to review:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">texra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install-github-action</span></span></code></pre></div><p>That command:</p><ol><li>Opens the <a href="https://github.com/apps/texra-ai-bot" target="_blank" rel="noreferrer">TeXRA GitHub App</a> installer so you can grant access to the repo (reviews then post as <code>texra-ai-bot[bot]</code>).</li><li>Writes <code>.github/workflows/texra-code-review.yml</code> on a branch.</li><li>Pushes and opens a pull-request page for you to create (or use <code>--no-pr</code> to stop after committing locally).</li></ol><p>Next, set <strong>one</strong> provider API key as a repository secret so the model can run. Prefer an open-weight option when you can:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DEEPSEEK_API_KEY</span></span></code></pre></div><p>(Or <code>OPENROUTER_API_KEY</code>, <code>GOOGLE_API_KEY</code>, <code>OPENAI_API_KEY</code>, <code>ANTHROPIC_API_KEY</code>, or <code>XAI_API_KEY</code>; names must match exactly. The action also accepts <code>MOONSHOT_API_KEY</code>, <code>DASHSCOPE_API_KEY</code>, <code>MINIMAX_API_KEY</code>, and <code>GLM_API_KEY</code>, but the scaffolded workflow only wires the first six, so for those you add the matching <code>moonshot-api-key</code>, <code>dashscope-api-key</code>, <code>minimax-api-key</code>, or <code>glm-api-key</code> input to the review step yourself.)</p><p>Merge the install PR to your default branch. From then on, same-repo PRs get a TeXRA review. Open the PR checks (or the repo <strong>Actions</strong> tab) and select <strong>TeXRA Code Review</strong> to watch a run.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>You must be able to install GitHub Apps on the repository and to add Actions secrets. If <code>gh pr create --web</code> fails with a workflow-scope error, run <code>gh auth refresh -h github.com -s workflow</code> and retry.</p></div><div class="warning custom-block"><p class="custom-block-title">Forks don&#39;t get reviewed</p><p>PRs opened from a <strong>fork</strong> are not reviewed. GitHub deliberately does not share your repo secrets with forks, so the workflow has nothing to talk to the model provider with and exits quietly. If a contributor needs a TeXRA review, push their branch into your repo (or to a topic branch you control) and reopen the PR from there.</p></div><h3 id="manual-setup" tabindex="-1">Manual setup <a class="header-anchor" href="#manual-setup" aria-label="Permalink to “Manual setup”">​</a></h3><p>Use this when you cannot run the CLI, when the installer fails, or when you want to review every YAML line yourself.</p><ol><li>Install the <a href="https://github.com/apps/texra-ai-bot" target="_blank" rel="noreferrer">TeXRA GitHub App</a> on the repository.</li><li>Add a provider API key under <strong>Settings → Secrets and variables → Actions</strong> (see the secret names in <a href="#quick-setup-recommended">Quick setup</a>).</li><li>Add <code>.github/workflows/texra-code-review.yml</code> from the <a href="https://github.com/texra-ai/texra-action/tree/main/examples" target="_blank" rel="noreferrer"><code>texra-ai/texra-action</code> examples</a> (start with <code>pr-review.yml</code>), commit it to the default branch, and open a test PR.</li></ol><p>The workflow needs <code>permissions.id-token: write</code> so the action can exchange a GitHub Actions OIDC token for a short-lived App installation token. Leave <code>github-token</code> unset unless you intentionally override App auth.</p><div class="tip custom-block"><p class="custom-block-title">Pin the action version for reproducible CI</p><p><code>@v1</code> tracks the latest v1.x release. To change review behavior only when you decide, pin a reviewed release commit (<code>uses: texra-ai/texra-action/review@&lt;full-commit-sha&gt;</code>) and bump it deliberately.</p></div><h2 id="picking-a-model" tabindex="-1">Picking a model <a class="header-anchor" href="#picking-a-model" aria-label="Permalink to “Picking a model”">​</a></h2><p>You can skip this section. By default TeXRA picks a model for whichever provider key you set, trying providers in this order: <strong>DeepSeek → Anthropic → OpenAI → Google → OpenRouter → xAI → Moonshot → DashScope → MiniMax → GLM</strong>.</p><p>The built-in defaults:</p><table tabindex="0"><thead><tr><th>Provider</th><th>Default model</th></tr></thead><tbody><tr><td>DeepSeek</td><td><code>deepseekproT</code></td></tr><tr><td>Anthropic</td><td><code>opus48T</code></td></tr><tr><td>OpenAI</td><td><code>gpt55</code></td></tr><tr><td>Google</td><td><code>gemini31p</code></td></tr><tr><td>OpenRouter</td><td><code>gptoss</code></td></tr><tr><td>xAI</td><td><code>grok4</code></td></tr><tr><td>Moonshot</td><td><code>kimi26T</code></td></tr><tr><td>DashScope</td><td><code>qwenplus</code></td></tr><tr><td>MiniMax</td><td><code>minimaxM27</code></td></tr><tr><td>GLM</td><td><code>glm51</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">xAI users</p><p>The action&#39;s xAI default, <code>grok4</code>, is retired in the current CLI and cannot be selected, so an xAI-only setup fails until the action&#39;s default is updated. Set <code>TEXRA_REVIEW_MODEL</code> to a current model such as <code>grok46</code> or <code>grok45</code>, or set <code>TEXRA_REVIEW_MODEL_DEFAULTS</code> to <code>{&quot;xai&quot;:&quot;grok46&quot;}</code>, and wire the variable through as described below.</p></div><p>To override, add a repo <strong>variable</strong>: the same place as secrets, but the <strong>Variables</strong> tab (Settings → Secrets and variables → Actions → <strong>Variables</strong> → <strong>New repository variable</strong>). Variables are plain, non-secret settings:</p><ul><li><code>TEXRA_REVIEW_MODEL</code>: pin one model id for every review, regardless of provider.</li><li><code>TEXRA_REVIEW_MODEL_DEFAULTS</code>: JSON map from provider id to default model id, used when you want provider-specific defaults. Example: <code>{&quot;deepseek&quot;:&quot;deepseekproT&quot;,&quot;anthropic&quot;:&quot;opus5T&quot;}</code>. This explicitly opts Anthropic reviews into Opus 5; the action&#39;s built-in default remains <code>opus48T</code>.</li></ul><p>The scaffolded workflow does not pass either variable yet: the <code>model</code> input is present only as a commented-out line, and there is no <code>model-defaults</code> input. Wire them through under the review step&#39;s <code>with:</code> block:</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${{ vars.TEXRA_REVIEW_MODEL }}</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">model-defaults</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${{ vars.TEXRA_REVIEW_MODEL_DEFAULTS }}</span></span></code></pre></div><p>An unset variable expands to an empty string, which the action treats as &quot;use the default&quot;.</p><div class="info custom-block"><p class="custom-block-title">Migrating from older setups</p><p>Older per-provider variables such as <code>TEXRA_REVIEW_DEEPSEEK_MODEL</code> are no longer read by the external action. Move those values into <code>TEXRA_REVIEW_MODEL_DEFAULTS</code>.</p></div><h2 id="writing-your-own-review-prompt" tabindex="-1">Writing your own review prompt <a class="header-anchor" href="#writing-your-own-review-prompt" aria-label="Permalink to “Writing your own review prompt”">​</a></h2><p>By default, the action reviews with its bundled general-purpose prompt. If you want reviews tailored to your project (&quot;focus on the math&quot;, &quot;enforce our naming conventions&quot;, &quot;be terse&quot;), you can supply your own prompt file that replaces the bundled one.</p><p>There is one security rule to understand first: <strong>read the prompt from the trusted base branch, not from the PR being reviewed.</strong> The prompt is the reviewer&#39;s instructions. If the workflow read it from the PR&#39;s own checkout, any PR could rewrite the instructions (for example to &quot;approve everything&quot;) before being reviewed. The pattern below checks the prompt out from the PR&#39;s <em>base</em> commit, so a PR can propose prompt changes but they only take effect after they are merged.</p><ol><li><p>Add your prompt at <code>.github/prompts/texra-code-review-prompt.md</code> on your default branch. Start from the bundled prompt in <a href="https://github.com/texra-ai/texra-action" target="_blank" rel="noreferrer"><code>texra-ai/texra-action</code></a> and edit the review-focus parts. The prompt file fully replaces the bundled instructions, so keep the parts describing the expected JSON review output intact.</p></li><li><p>In the workflow, add a second checkout step after &quot;Checkout pull request&quot;:</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Checkout trusted review prompt</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">steps.keys.outputs.present == &#39;true&#39; &amp;&amp; steps.merge-ref.outputs.available == &#39;true&#39;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  uses</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">actions/checkout@v6</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${{ github.event.pull_request.base.sha }}</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.trusted-review-prompt</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    sparse-checkout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.github/prompts/texra-code-review-prompt.md</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    sparse-checkout-cone-mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    persist-credentials</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div></li><li><p>Point the review step at the trusted copy by adding one input:</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">prompt-file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.trusted-review-prompt/.github/prompts/texra-code-review-prompt.md</span></span></code></pre></div></li></ol><p>To go back to the bundled prompt, remove the <code>prompt-file</code> input and the extra checkout step.</p><h2 id="pinning-the-texra-cli-version" tabindex="-1">Pinning the TeXRA CLI version <a class="header-anchor" href="#pinning-the-texra-cli-version" aria-label="Permalink to “Pinning the TeXRA CLI version”">​</a></h2><p>By default the workflow installs the latest published <code>texra</code> CLI on each run. To pin a specific version (for example, for reproducibility), add a <code>texra-version</code> input to the review step. The scaffolded workflow carries it as a commented-out example; uncomment it with a literal version, or read it from a repository variable:</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">texra-version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${{ vars.TEXRA_CLI_VERSION }}</span></span></code></pre></div><p>Then set <code>TEXRA_CLI_VERSION</code> to the version you want: <code>0.40.3</code>, <code>latest</code>, or empty for latest. The action supports <code>@texra-ai/cli</code> 0.40.3 and newer.</p><h2 id="everyday-controls" tabindex="-1">Everyday controls <a class="header-anchor" href="#everyday-controls" aria-label="Permalink to “Everyday controls”">​</a></h2><h3 id="pausing-reviews" tabindex="-1">Pausing reviews <a class="header-anchor" href="#pausing-reviews" aria-label="Permalink to “Pausing reviews”">​</a></h3><p>Set the repository variable <code>TEXRA_REVIEW_ENABLED</code> to <code>false</code> to pause TeXRA reviews without removing the workflow file. Set it back to anything else (or unset it) to resume.</p><h3 id="letting-texra-resolve-its-own-threads" tabindex="-1">Letting TeXRA resolve its own threads <a class="header-anchor" href="#letting-texra-resolve-its-own-threads" aria-label="Permalink to “Letting TeXRA resolve its own threads”">​</a></h3><p>With <code>resolve-threads: &#39;true&#39;</code> on the review step (as in the richer examples under <a href="https://github.com/texra-ai/texra-action" target="_blank" rel="noreferrer"><code>texra-ai/texra-action</code></a>), the TeXRA GitHub App can resolve fixed findings and reply to earlier threads under the same bot identity. No personal access token is needed.</p><h3 id="choosing-whose-prs-get-reviewed" tabindex="-1">Choosing whose PRs get reviewed <a class="header-anchor" href="#choosing-whose-prs-get-reviewed" aria-label="Permalink to “Choosing whose PRs get reviewed”">​</a></h3><p><code>require-write-access: &#39;true&#39;</code> limits reviews to PRs authored by users with write access, so outside accounts cannot spend your API budget. Allow-list trusted bots with <code>allow-bots</code> (comma-separated), for example <code>dependabot[bot]</code>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><h3 id="my-pr-didn-t-get-a-review" tabindex="-1">My PR didn&#39;t get a review <a class="header-anchor" href="#my-pr-didn-t-get-a-review" aria-label="Permalink to “My PR didn&#39;t get a review”">​</a></h3><p>Work down this checklist; each item maps to a quiet skip:</p><ol><li><strong>Is the workflow on the default branch?</strong> PRs only trigger it once <code>.github/workflows/texra-code-review.yml</code> exists on your default branch (usually <code>main</code>), or the PR itself contains it.</li><li><strong>Is the PR from a fork?</strong> Fork PRs are skipped because secrets are not shared with forks (see the warning above).</li><li><strong>Is the secret named exactly right?</strong> A typo like <code>ANTHROPIC_KEY</code> means no key is found; the run logs a &quot;no model provider API key&quot; notice and skips.</li><li><strong>Does the PR have a merge conflict?</strong> GitHub cannot produce a merge preview for conflicted PRs, so there is nothing to review. Resolve the conflict and push.</li><li><strong>Is <code>TEXRA_REVIEW_ENABLED</code> set to <code>false</code>?</strong> Unset it or set it to <code>true</code>.</li><li><strong>Does the PR author have write access?</strong> With <code>require-write-access</code> enabled, PRs from non-writers (and non-allow-listed bots) are skipped.</li></ol><p>In every case the <strong>Actions</strong> tab shows the run (or its absence) and a notice explaining the skip.</p><h3 id="the-check-failed" tabindex="-1">The check failed <a class="header-anchor" href="#the-check-failed" aria-label="Permalink to “The check failed”">​</a></h3><p>If the model provider or CLI run fails, the action fails the workflow check instead of posting a fallback review. Treat that failed check as the signal that no review was completed. Open the run log from the <strong>Actions</strong> tab to see the error. Common causes are an expired or out-of-credit API key and provider outages. Use <strong>Re-run failed jobs</strong> on the run page to try again.</p><h3 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to “Common questions”">​</a></h3><p><strong>Where does my code go?</strong> From GitHub&#39;s runner directly to the model provider your key belongs to, and nowhere else. No TeXRA service sees your code or diffs.</p><p><strong>What does it cost?</strong> Whatever your provider charges for the tokens in the review call, billed to your API key like any other usage. No TeXRA account or subscription is involved.</p><p><strong>Can I add keys for several providers?</strong> Yes. TeXRA uses the first available provider in its default order (DeepSeek → Anthropic → OpenAI → Google → OpenRouter → xAI → Moonshot → DashScope → MiniMax → GLM), or exactly what you pin via <code>TEXRA_REVIEW_MODEL</code>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next steps”">​</a></h2><ul><li><a href="./texra-cli.html">TeXRA CLI</a>: the <code>texra</code> command the action runs.</li><li><a href="./built-in-agents.html#review">Built-in agents</a>: what the <code>review</code> agent checks.</li></ul>`,63)]))}});export{S as __pageData,C as default};